  let sequence=0;
  function render(path,prefix){
    if(!Object.prototype.hasOwnProperty.call(sources,path))return '';
    const idPrefix=typeof prefix==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(prefix)
      ?prefix:'hl-monthly-figure-'+(++sequence);
    return sources[path]
      .replace(/id="([^"]+)"/g,(_,id)=>'id="'+idPrefix+'-'+id+'"')
      .replace(/url\(#([^)]+)\)/g,(_,id)=>'url(#'+idPrefix+'-'+id+')')
      .replace(/aria-labelledby="([^"]+)"/g,(_,ids)=>'aria-labelledby="'+ids.split(/\s+/).map(id=>idPrefix+'-'+id).join(' ')+'"');
  }
  return Object.freeze({paths:Object.freeze(Object.keys(sources)),render});
